parameters.jsCode:
const raw = $input.first().json.output || '';

// Extrair conteúdo final
const conteudoMatch = raw.match(/===CONTEÚDO FINAL===([\s\S]*?)===FIM DO CONTEÚDO===/i);
const conteudo_final = conteudoMatch ? conteudoMatch[1].trim() : raw;

// Extrair melhorias
const melhorasMatch = raw.match(/===MELHORIAS APLICADAS===([\s\S]*?)===FIM DAS MELHORIAS===/i);
const melhorias_raw = melhorasMatch ? melhorasMatch[1].trim() : '';
const melhorias = melhorias_raw.split('\n').filter(l => l.match(/^\d+\./)).map(l => l.replace(/^\d+\.\s*/, '').trim());

// Extrair scores
const scoresMatch = raw.match(/===SCORES===([\s\S]*?)===FIM DOS SCORES===/i);
const scores_raw = scoresMatch ? scoresMatch[1].trim() : '';

const extractScore = (label) => {
  const m = scores_raw.match(new RegExp(label + '[:\\s]+(\\d+(?:\\.\\d+)?)\/10', 'i'));
  return m ? parseFloat(m[1]) : null;
};

const scores = {
  clareza: extractScore('Clareza'),
  impacto: extractScore('Impacto'),
  originalidade: extractScore('Originalidade'),
  hook: extractScore('Hook'),
  conversao: extractScore('Convers'),
  score_v1: extractScore('Score médio v1'),
  score_final: extractScore('Score médio final')
};

const score_medio = (() => {
  const vals = [scores.clareza, scores.impacto, scores.originalidade, scores.hook, scores.conversao].filter(Boolean);
  return vals.length ? Math.round((vals.reduce((a,b) => a+b, 0) / vals.length) * 10) / 10 : null;
})();

const ganho = scores.score_v1 && scores.score_final ? Math.round((scores.score_final - scores.score_v1) * 10) / 10 : null;

return [{
  json: {
    conteudo_v1: $('Salvar V1').item.json.conteudo_v1,
    conteudo_final,
    melhorias,
    scores,
    score_medio_final: score_medio,
    ganho_percentual: ganho,
    tema: $('Salvar V1').item.json.tema,
    objetivo: $('Salvar V1').item.json.objetivo,
    publico: $('Salvar V1').item.json.publico,
    canal: $('Salvar V1').item.json.canal,
    critica_editor: $('Editor Agent').item.json.output,
    critica_growth: $('Growth Agent').item.json.output,
    critica_hater: $('Hater Agent').item.json.output,
    reacoes_audiencia: $('Audience Simulator').item.json.output,
    timestamp: new Date().toISOString()
  }
}];

